update public.question_solutions set final_answer_markdown='Porque ficam próximos à ULA e têm pouca capacidade.', explanation_markdown='Níveis superiores trocam capacidade por baixa latência. No caso apresentado, Compare distância e quantidade de dados guardados. Velocidade não elimina a limitação de capacidade. Logo, “Porque ficam próximos à ULA e têm pouca capacidade.” é a conclusão correta. “Porque são não voláteis.” não cumpre o critério técnico do caso: Velocidade não elimina a limitação de capacidade. “Porque usam disco.” não decorre do princípio aplicável: Níveis superiores trocam capacidade por baixa latência. “Porque não armazenam dados.” deixa de executar a análise necessária: Compare distância e quantidade de dados guardados.' where question_id='40000000-0000-4000-8000-000000930076';
