update public.question_solution_steps set title='Analise os distratores', content_markdown='“RAM, cache, registradores, SSD.” não cumpre o critério técnico do caso: Registradores são o nível mais imediato da CPU. “SSD, RAM, cache, registradores.” não decorre do princípio aplicável: A hierarquia aproxima os dados mais usados do processador. “Cache, registradores, SSD, RAM.” deixa de executar a análise necessária: Ordene por latência típica.', sort_order=4 where id='70000000-0000-4000-8000-000009300774';
