update public.question_solution_steps set title='Aplique o critério', content_markdown='Compare o índice atual com o próximo. No enunciado, Uma rotina percorre um vetor em índices consecutivos. Que localidade é favorecida? A próxima posição provavelmente já veio no mesmo bloco.', sort_order=3 where id='70000000-0000-4000-8000-000009300793';
