update public.question_solutions set final_answer_markdown='Miss por conflito.', explanation_markdown='Mapeamento restrito pode expulsar blocos úteis entre si. No caso apresentado, Observe que os blocos competem por uma única linha. Alternância causa substituições mesmo com cache pouco cheia. Logo, “Miss por conflito.” é a conclusão correta. “Miss compulsório apenas.” não cumpre o critério técnico do caso: Alternância causa substituições mesmo com cache pouco cheia. “Hit de escrita.” não decorre do princípio aplicável: Mapeamento restrito pode expulsar blocos úteis entre si. “Falha de página.” deixa de executar a análise necessária: Observe que os blocos competem por uma única linha.' where question_id='40000000-0000-4000-8000-000000930083';
