update public.question_solutions set final_answer_markdown='Cada escrita atualiza cache e nível inferior.', explanation_markdown='Write-through simplifica consistência, mas gera tráfego. No caso apresentado, Acompanhe o destino da escrita após atualizar a cache. A memória inferior recebe a alteração imediatamente. Logo, “Cada escrita atualiza cache e nível inferior.” é a conclusão correta. “Escreve só no disco.” não cumpre o critério técnico do caso: A memória inferior recebe a alteração imediatamente. “Nunca atualiza memória.” não decorre do princípio aplicável: Write-through simplifica consistência, mas gera tráfego. “Remove a cache.” deixa de executar a análise necessária: Acompanhe o destino da escrita após atualizar a cache.' where question_id='40000000-0000-4000-8000-000000930084';
