update public.question_solutions set final_answer_markdown='Quando é substituída ou explicitamente sincronizada.', explanation_markdown='Write-back adia propagação até a linha deixar a cache. No caso apresentado, Relacione dirty bit à necessidade de preservar alteração. A substituição não pode descartar uma alteração não propagada. Logo, “Quando é substituída ou explicitamente sincronizada.” é a conclusão correta. “Em toda leitura.” não cumpre o critério técnico do caso: A substituição não pode descartar uma alteração não propagada. “Antes de toda escrita.” não decorre do princípio aplicável: Write-back adia propagação até a linha deixar a cache. “Nunca.” deixa de executar a análise necessária: Relacione dirty bit à necessidade de preservar alteração.' where question_id='40000000-0000-4000-8000-000000930085';
