update public.question_solutions set final_answer_markdown='A página virtual referenciada não está na RAM.', explanation_markdown='Memória virtual precisa trazer a página ausente do armazenamento. No caso apresentado, Diferencie página de linha de cache. A execução só continua após resolver o mapeamento. Logo, “A página virtual referenciada não está na RAM.” é a conclusão correta. “A cache acertou.” não cumpre o critério técnico do caso: A execução só continua após resolver o mapeamento. “O PC é inválido.” não decorre do princípio aplicável: Memória virtual precisa trazer a página ausente do armazenamento. “O disco foi removido.” deixa de executar a análise necessária: Diferencie página de linha de cache.' where question_id='40000000-0000-4000-8000-000000930086';
