update public.question_solutions set final_answer_markdown='Acelerar tradução de endereços virtuais recentes.', explanation_markdown='TLB é uma cache de traduções de página. No caso apresentado, Pergunte qual informação é reutilizada antes de acessar memória. Hit no TLB evita consultar a tabela de páginas. Logo, “Acelerar tradução de endereços virtuais recentes.” é a conclusão correta. “Guardar instruções da ULA.” não cumpre o critério técnico do caso: Hit no TLB evita consultar a tabela de páginas. “Substituir o SSD.” não decorre do princípio aplicável: TLB é uma cache de traduções de página. “Corrigir paridade.” deixa de executar a análise necessária: Pergunte qual informação é reutilizada antes de acessar memória.' where question_id='40000000-0000-4000-8000-000000930087';
