update public.question_solution_steps set title='Analise os distratores', content_markdown='“4 bytes.” não cumpre o critério técnico do caso: $64/8=8$ bytes por transferência. “16 bytes.” não decorre do princípio aplicável: Oito bits formam um byte. “64 bytes.” deixa de executar a análise necessária: Converta largura em bits para bytes.', sort_order=4 where id='70000000-0000-4000-8000-000009300974';
update public.question_solution_steps set title='Verifique a conclusão', content_markdown='A alternativa correta é “8 bytes.”, pois é a única que respeita o princípio e o cenário apresentados.', sort_order=5 where id='70000000-0000-4000-8000-000009300975';

update public.question_solutions set final_answer_markdown='$3,2$ GB/s.', explanation_markdown='Largura de banda é bytes por transferência vezes transferências por segundo. No caso apresentado, Calcule $16	imes200,000,000$. O resultado é $3,2$ bilhões de bytes por segundo. Logo, “$3,2$ GB/s.” é a conclusão correta. “$200$ MB/s.” não cumpre o critério técnico do caso: O resultado é $3,2$ bilhões de bytes por segundo. “$16$ GB/s.” não decorre do princípio aplicável: Largura de banda é bytes por transferência vezes transferências por segundo. “$1,6$ GB/s.” deixa de executar a análise necessária: Calcule $16	imes200,000,000$.' where question_id='40000000-0000-4000-8000-000000930098';
update public.question_solution_steps set title='Delimite o problema', content_markdown='O enunciado apresenta esta situação de largura de banda: Um barramento transfere 16 bytes por ciclo a 200 MHz. Qual pico teórico?', sort_order=1 where id='70000000-0000-4000-8000-000009300981';
update public.question_solution_steps set title='Recupere o princípio', content_markdown='Largura de banda é bytes por transferência vezes transferências por segundo.', sort_order=2 where id='70000000-0000-4000-8000-000009300982';
update public.question_solution_steps set title='Aplique o critério', content_markdown='Calcule $16	imes200,000,000$. No enunciado, Um barramento transfere 16 bytes por ciclo a 200 MHz. Qual pico teórico? O resultado é $3,2$ bilhões de bytes por segundo.', sort_order=3 where id='70000000-0000-4000-8000-000009300983';
update public.question_solution_steps set title='Analise os distratores', content_markdown='“$200$ MB/s.” não cumpre o critério técnico do caso: O resultado é $3,2$ bilhões de bytes por segundo. “$16$ GB/s.” não decorre do princípio aplicável: Largura de banda é bytes por transferência vezes transferências por segundo. “$1,6$ GB/s.” deixa de executar a análise necessária: Calcule $16	imes200,000,000$.', sort_order=4 where id='70000000-0000-4000-8000-000009300984';
update public.question_solution_steps set title='Verifique a conclusão', content_markdown='A alternativa correta é “$3,2$ GB/s.”, pois é a única que respeita o princípio e o cenário apresentados.', sort_order=5 where id='70000000-0000-4000-8000-000009300985';

update public.question_solutions set final_answer_markdown='Reduz o risco de starvation de solicitantes menos prioritários.', explanation_markdown='Round-robin alterna concessões entre solicitantes. No caso apresentado, Compare quem pode ficar esperando indefinidamente. Justiça não garante que cada requisição tenha mesma latência. Logo, “Reduz o risco de starvation de solicitantes menos prioritários.” é a conclusão correta. “Sempre minimiza latência.” não cumpre o critério técnico do caso: Justiça não garante que cada requisição tenha mesma latência. “Elimina colisões elétricas.” não decorre do princípio aplicável: Round-robin alterna concessões entre solicitantes. “Dispensa protocolo.” deixa de executar a análise necessária: Compare quem pode ficar esperando indefinidamente.' where question_id='40000000-0000-4000-8000-000000930099';
